    let computed = accessors::get_beacon_proposer_index(&self.chain_config, &state)?;

    ensure!(
        block_header.proposer_index == computed,
        Error::DataColumnSidecarProposerIndexMismatch {
            data_column_sidecar,
            computed,
        }
    );
}

